"""Lesson simulators: queued as ``demo_builder`` jobs, generated by the engine, saved under viz/demos/."""
from __future__ import annotations

import logging
from typing import Any

from learnharness.core.events import SseEventType
from learnharness.mcp.demo_builder import generate_demo, link_demo_in_lesson, save_demo_html
from learnharness.vault.safety import safe_path

logger = logging.getLogger(__name__)

MAX_LESSON_CONTEXT_CHARS = 12_000


def submit_demo(state, title: str, topic: str, description: str = "", lesson_rel_path: str | None = None,
                session_id: str | None = None) -> dict[str, Any]:
    """Queue a ``demo_builder`` job and return its record immediately (never blocks a teaching turn)."""
    if session_id and not lesson_rel_path:
        try:
            lesson_rel_path = state.sessions.get(session_id).lesson_vault_path
        except KeyError:
            session_id = None
    payload = {"title": title, "topic": topic, "description": description,
               "lesson_rel_path": lesson_rel_path, "session_id": session_id}
    return state.jobs.submit("demo_builder", payload)


def build_demo_context(state, *, topic: str, lesson_rel_path: str | None, session_id: str | None) -> dict[str, Any]:
    """Collect lesson data (note text, current plan node) passed to the engine as data."""
    context: dict[str, Any] = {"topic": topic}
    if lesson_rel_path:
        try:
            note = safe_path(state.vault_path, lesson_rel_path.strip().lstrip("/"))
            if note.is_file():
                context["lesson_note"] = note.read_text(encoding="utf-8")[:MAX_LESSON_CONTEXT_CHARS]
        except (OSError, UnicodeDecodeError, PermissionError) as err:
            logger.warning("Could not read lesson note %s for demo context: %s", lesson_rel_path, err)
    if session_id:
        try:
            session = state.sessions.get(session_id)
        except KeyError:
            session = None
        if session is not None:
            context["session_title"] = session.title
            current = [n for n in session.plan.nodes if n.status == "current"]
            if current:
                context["current_plan_node"] = current[0].model_dump(mode="json", exclude_none=True)
            if session.plan.approach_prose:
                context["plan_approach"] = session.plan.approach_prose
    return context


async def run_demo_job(state, payload: dict[str, Any]) -> dict[str, Any]:
    """Job body: generate (engine ``background`` slot), validate, save, link into the lesson note."""
    config = state.get_config()
    slot = config.slots.background
    context = build_demo_context(state, topic=payload["topic"], lesson_rel_path=payload.get("lesson_rel_path"),
                                 session_id=payload.get("session_id"))
    demo = await generate_demo(state.engine(slot), slot, title=payload["title"], topic=payload["topic"],
                               description=payload.get("description", ""), context=context)
    result = save_demo_html(state.vault_path, demo, topic=payload["topic"],
                            description=payload.get("description") or demo.learning_goal)
    lesson = payload.get("lesson_rel_path")
    if lesson:
        try:
            link_demo_in_lesson(state.vault_path, lesson, slug=result["slug"], title=demo.title,
                                description=payload.get("description") or demo.learning_goal)
        except (OSError, ValueError, RuntimeError) as err:
            # The simulator itself was saved; a note conflict must not discard it.
            logger.warning("Failed to link demo into lesson note %s: %s", lesson, err)
    state.sse_hub.broadcast(SseEventType.VAULT_CHANGED, {"demo": result["slug"]})
    return result
